style.css:
:root {
  --color-bg-base: #262628;
  --color-bg-secondary: #1c1c1d;
  --color-border-base: #333333;
  --color-fg-base: #d0d3d8;

  --color-bg-report-info: var(--color-bg-base);
  --color-bg-header: var(--color-bg-base);
  --color-bg-section: var(--color-bg-base);
  --color-bg-choice: var(--color-bg-base);
  --color-bg-textarea: var(--color-bg-secondary);
  --color-bg-choice-sub: var(--color-bg-secondary);
  --color-bg-question-overall: var(--color-bg-secondary);
  --color-bg-report-ability-change: var(--color-bg-secondary);
  --color-bg-report-ability-change-section: linear-gradient(270deg, rgba(30, 35, 45, .17) 0%, #1a1f2e 100%);
  --color-bg-question-correct: linear-gradient(182.53342deg, rgba(31, 56, 41, 0.8) -4%, rgba(30, 35, 45, 0) 67%);
  --color-bg-question-wrong: linear-gradient(182.8052deg, rgba(56, 31, 26, 0.8) -3%, rgba(30, 35, 45, 0) 60%);
  --color-bg-label-correct: rgba(31, 56, 41, 0.6);
  --color-bg-label-wrong: rgba(56, 31, 26, 0.6);
  --color-bg-report-ability-change-1: var(--color-bg-base);
  --color-bg-report-ability-change-2: #2d1f15;

  --color-text-primary: var(--color-fg-base); /* 图标线条基础色 */
  --color-text-icon: var(--color-fg-base); /* 文字基础色 */
  --color-text-report-title: var(--color-fg-base);
  --color-text-choice: var(--color-fg-base);

  --color-svg-fill-1: var(--color-bg-secondary); /* 图标背景 */
  --color-svg-fill-2: var(--color-fg-base); /* 图标外框 */
  --color-svg-fill-3: var(--color-fg-base); /* 图标线条 */
  --color-svg-fill-9: var(--color-fg-base); /* 图标线条 */
  --color-bg-result-common: var(--color-bg-secondary);
  --color-border-result-common: var(--color-border-base);
  --color-border-setting: var(--color-border-base);
  --color-border-choice: var(--color-border-base);
  --color-border-section: var(--color-border-base);
  --color-border-textarea: var(--color-border-base);
  --color-border-report-info: var(--color-border-base);

  --report-score-info-bg-image-left: none;
  --report-score-info-bg-image-right: none;
}

body {
  background: var(--color-bg-secondary) !important;
}

[id*="section-video"]:has(app-solution-video) {
  display: none;
}
